def get_cluster_centers(demo):
    """Get geometric center of each non-1 value cluster."""
    cluster_positions = {}
    for (r, c, val) in demo['non_ones']:
        if val not in cluster_positions:
            cluster_positions[val] = []
        cluster_positions[val].append((r, c))

    cluster_centers = {}
    for val, pts in cluster_positions.items():
        cmtr = (sum(p[0] for p in pts)/len(pts), sum(p[1] for p in pts)/len(pts))
